const stamp = (iso: string) => formatSourceStamp(new Date(Date.parse(iso)).toISOString());
const texts = (slots: HockeyJourneySlot[]) => slots.map((s) => s.text);
const spoken = (slots: HockeyJourneySlot[]) => slots.map((s) => (s.kind === "value" ? s.spoken : `[${s.text}]`));

/**
 * HOST EMULATION (CONSTRUCTED): the page's own hero pair, accepted price clock and
 * live-claim answer for a body. `resolveProbability` gets page.tsx's own arguments
 * (:1945-1979): `isLive` = status live and started (:480), `isFinished` (:481),
 * `isSuspended` = `hasNoReportedResult(…) || liveClaimUnbacked` (:753-759), and the
 * caption staleness `blendCaptionIsStale(heroStampIsStale, liveClaimUnbacked)` with
 * the badge age taken as fresh (it is host-level and not in the capture).
 * `liveClaimUnbacked` is the page owner's `pageLiveClaimIsUnbacked` answer; the
 * retained captures carry no page-level blend age or pin state, so it is a
 * CONSTRUCTED flag: `false` (backed) for every real-specimen read, `true` only in
 * the labelled TEST MUTATION.
 */
function pageHost(
  event: EventDetailResponse,
  history: EventHistoryResponse | null,
  nowIso: string,
  liveClaimUnbacked: boolean,
): FootballJourneyHost {
  const now = Date.parse(nowIso);
  const start = Date.parse(event.commence_time);
  const isLive = event.status === "live" && Number.isFinite(start) && start <= now;
  const isSuspended =
    hasNoReportedResult(event.status, event.commence_time, now, event.started_without_result) || liveClaimUnbacked;
  const resolved = resolveProbability(
    event,
    history ?? undefined,
    null,
    isLive,
    isFinishedStatus(event.status),
    isSuspended,
    blendCaptionIsStale(false, liveClaimUnbacked),
    true,
  );
  return {
    liveClaimUnbacked,
    nowMs: Date.parse(nowIso),
    hero: {
      homeProb: resolved.homeProb,
      awayProb: resolved.awayProb,
      homePct: resolved.homePct,
      awayPct: resolved.awayPct,
      probSourceLabel: resolved.probSourceLabel,
    },
    probabilityObservedAt:
      resolved.selectedProbabilitySource === "hero-blend" ? event.hero_probability_observed_at ?? null : null,
  };
}

function journey(model: FootballJourneyModel): FootballJourneyView {
  if (model.kind !== "journey") throw new Error(`refused: ${model.reason}`);
  return model;
}

/** CONSTRUCTED host flag for every real-specimen read: the page's live claim is backed. */
const CLAIM_BACKED = false;

function build(event: EventDetailResponse, history: EventHistoryResponse | null, nowIso: string, host?: Partial<FootballJourneyHost>) {
  const unbacked = host?.liveClaimUnbacked ?? CLAIM_BACKED;
  return journey(buildFootballJourney({ event, history, host: { ...pageHost(event, history, nowIso, unbacked), ...host } }));
}

const iso = (t: number) => new Date(t).toISOString();

