describe("BEFORE — Rams–Bills 14780558 (retained)", () => {
  const view = build(rams, ramsHistory, RAMS_NOW);
  const { matrix } = view.headline;

  it("applies to an NFL row in a known state, and is before", () => {
    expect(footballJourneyApplies(rams.sport)).toBe(true);
    expect(view.phase).toBe("before");
    expect(view.eventId).toBe(14780558);
    expect(view.headline.state).toMatch(/^Before game · .+ start$/);
  });

  it("prints the hero's own chance under its currentness role and the sportsbook projected final in points", () => {
    expect(matrix.columns.map((c) => c.title)).toEqual([MATRIX_WORDS.currentChance, "Projected final"]);
    expect(matrix.rows.map((r) => r.side)).toEqual(["home", "away"]);
    expect(texts(matrix.rows[0].values)).toEqual(["62%", "29"]);
    expect(texts(matrix.rows[1].values)).toEqual(["38%", "25.4"]);
    expect(spoken(matrix.rows[1].values)).toEqual(["38 percent", "25.4 points"]);
    expect(matrix.lead).toBe(0);
    expect(matrix.groups).toEqual([[0, 1]]);
    expect(matrix.rows.every((r) => r.result === null)).toBe(true);
  });

  it("moves each column's source and clock into Info, and offers both destinations", () => {
    expect(view.info).toEqual({
      label: MATRIX_WORDS.aboutLabel,
      lines: [
        `${MATRIX_WORDS.currentChance}: Recorded ${stamp("2026-10-12T05:45:00.084170+00:00")}`,
        "Projected final: Before the start · 22 sportsbooks",
      ],
    });
    expect(view.forecastAction).toEqual({ label: FOOTBALL_WORDS.openForecast });
    expect(view.historyAction).toEqual({ label: FOOTBALL_WORDS.openHistory });
    expect(view.earlierForecast).toBeNull();
  });

  it("draws the day ending at the last pregame reading: 1,142 of 1,143 served blend rows", () => {
    const h = view.history;
    const kickoff = Date.parse(rams.commence_time);
    const served = ramsHistory.aggregate_line ?? [];
    // The window's floor is each side's own last pregame reading (05:44 Oct 12, the last row before
    // the pinned 05:45 edge) less one day, inclusive — not the listed start less one day, which
    // would drop 832 earlier real rows from a capture that ended 18.5 h before kick-off.
    const lastPregame = Date.parse("2026-10-12T05:44:00Z");
    const floor = lastPregame - BEFORE_WINDOW_MS;
    expect(served).toHaveLength(1143);
    expect(served.filter((p) => Date.parse(p.timestamp) < kickoff - BEFORE_WINDOW_MS)).toHaveLength(832);
    expect(served.filter((p) => Date.parse(p.timestamp) < floor)).toHaveLength(0);
    expect(h.line).toBe("blend");
    expect(h.caption).toBe(HISTORY_WORDS.beforeCaption);
    for (const series of h.series) {
      expect(series.runs).toHaveLength(1);
      expect(series.runs[0]).toHaveLength(1142);
    }
    // The whole recorded day ending at the last pregame row: 05:45 Oct 11 to 05:44 Oct 12; the
    // pinned 05:45 edge row is removed.
    expect(h.domain && [iso(h.domain.lower), iso(h.domain.upper)]).toEqual([
      "2026-10-11T05:45:00.000Z",
      "2026-10-12T05:44:00.000Z",
    ]);
    expect(h.series[0].before).toMatchObject({ kind: "reading", figure: "62%" });
    expect(h.series[1].before).toMatchObject({ kind: "reading", figure: "38%" });
    expect(h.series.map((s) => s.recorded)).toEqual([
      { kind: "absent", words: HISTORY_WORDS.notRecorded },
      { kind: "absent", words: HISTORY_WORDS.notRecorded },
    ]);
    expect(h.guides).toEqual([]);
    expect(h.readout).toBe("single");
    expect(view.historyForeign).toBe(false);
  });
});

