    const v = journey(buildFootballJourney({ event: ladderOnly, history: jagLiveHistory, host: host() }));
    expect(v.historyForeign).toBe(true);
    expect(v.history.absence?.title).toBe(HISTORY_WORDS.historyUnavailable);
    expect(v.historyAction).toBeNull();
    expect(texts(v.headline.matrix.rows.map((r) => r.values[1]))).toEqual([MATRIX_WORDS.noPregameForecast, MATRIX_WORDS.noPregameForecast]);
    expect(v.headline.matrix.columns[1].provenance).toBeNull();
    expect(v.forecastAction).toBeNull();
    expect(texts(v.headline.matrix.rows.map((r) => r.values[0]))).toEqual(["62%", "38%"]);
