    expect(v.headline.stateContext).toBeNull();
    expect(texts(v.headline.matrix.rows.map((r) => r.values[1]))).toEqual([MATRIX_WORDS.forecastWithheld, MATRIX_WORDS.forecastWithheld]);
    expect(v.headline.matrix.columns[1].provenance).toBeNull();
    expect(v.forecastAction).toBeNull();
    expect(v.headline.matrix.columns[0].title).toBe(MATRIX_WORDS.lastRecordedChance);
    expect(texts(v.headline.matrix.rows.map((r) => r.values[0]))).toEqual(["62%", "38%"]);
    expect(v.historyForeign).toBe(false);
    expect(v.history.absence).toBeNull();
    expect(v.historyAction).toEqual({ label: FOOTBALL_WORDS.openHistory });
    // The served TRUE is the server's answer even inside the grace.
    const early = build(event, ramsHistory, iso(kickoff + 10 * 60 * 1000));
    expect(early.headline.state).toBe(SUSPENDED_LABEL);
    expect(early.forecastAction).toBeNull();
